    "preview": "# Proxyfuzz: a TCP and UDP proxy man-in-the-middle fuzzer\n# v 0.1\n# By Rodrigo Marcos\n# http://www.theartoffuzzing.com\n\nfrom twisted.protocols import portforward\nfrom twisted.internet.protocol import DatagramProtocol\nfrom twisted.internet import reactor\nimport getopt, sys\nfrom random import randint\n\n\n# UDP Proxy stuff\n\nclass Client(DatagramProtocol):\n\tdef __init__(self, server, host, port):\n\t\tself",
    "fullContent": "# Proxyfuzz: a TCP and UDP proxy man-in-the-middle fuzzer\n# v 0.1\n# By Rodrigo Marcos\n# http://www.theartoffuzzing.com\n\nfrom twisted.protocols import portforward\nfrom twisted.internet.protocol import DatagramProtocol\nfrom twisted.internet import reactor\nimport getopt, sys\nfrom random import randint\n\n\n# UDP Proxy stuff\n\nclass Client(DatagramProtocol):\n\tdef __init__(self, server, host, port):\n\t\tself.server = server\n\t\tself.host = host\n\t\tself.port = port\n    \n\tdef startProtocol(self):\n\t\tself.transport.connect(desthost, destport)\n    \n\tdef datagramReceived(self, data, (host, port)):\n\t\tglobal verbose\n\t\tglobal notuntil\n\t\tglobal request\n\t\tglobal testclient\n\t\n\t\tif testclient:\n\t\t\tif request < notuntil:\n\t\t\t\trequest = request + 1\n\t\t\telse:\n\t\t\t\tdata = fuzz(data)\n\t\tif verbose:\n\t\t\tprint \"Server ------> Client\"\n\t\t\tprint \"%r\" % data\n\t\t\n\t        self.server.transport.write(data, (self.host, self.port))\n \nclass Server(DatagramProtocol):\n\tclient = None\n    \n\tdef datagramReceived(self, data, (host, port)):\n\t\tif not self.client or self.client.host != host or self.client.port != port:\n\t\t\tself.client = Client(self, host, port)\n\t\t\treactor.listenUDP(0, self.client)\n\n\t\tglobal verbose\n\t\tglobal notuntil\n\t\tglobal request\n\t\tglobal testserver\n\t\t\n\t\tif testserver:\n\t\t\tif request < notuntil:\n\t\t\t\trequest = request + 1\n\t\t\telse:\n\t\t\t\tdata = fuzz(data)\n\t\tif verbose:\n\t\t\tprint \"Client ------> Server\"\n\t\t\tprint \"%r\" % data \n\t\tself.client.transport.write(data, (desthost, destport))\n \n# TCP proxy stuff\n\ndef server_dataReceived(self, data):\n\tglobal verbose\n\tglobal notuntil\n\tglobal request\n\tglobal testserver\n\t\n\tif testserver:\n\t\tif request < notuntil:\n\t\t\trequest = request + 1\n\t\telse:\n\t\t\tdata = fuzz(data)\n\n\tif verbose:\n\t\tprint \"Client ------> server\"\n\t\tprint \"%r\" % data\n\t\t\n\tportforward.Proxy.dataReceived(self, data)\n\nportforward.ProxyServer.dataReceived = server_dataReceived\n\ndef client_dataReceived(self, data):\n\tglobal verbose\n\tglobal notuntil\n\tglobal request\n\tglobal testclient\n\t\n\tif testclient:\n\t\tif request < notuntil:\n\t\t\trequest = request + 1\n\t\telse:\n\t\t\tdata = fuzz(data)\n\tif verbose:\n\t\tprint \"Server ------> Client\"\n\t\tprint \"%r\" % data\n\t\n\tportforward.Proxy.dataReceived(self, data)\n\nportforward.ProxyClient.dataReceived = client_dataReceived\n\n       \noverflowstrings = [\"A\" * 255, \"A\" * 256, \"A\" * 257, \"A\" * 420, \"A\" * 511, \"A\" * 512, \"A\" * 1023, \"A\" * 1024, \"A\" * 2047, \"A\" * 2048, \"A\" * 4096, \"A\" * 4097, \"A\" * 5000, \"A\" * 10000, \"A\" * 20000, \"A\" * 32762, \"A\" * 32763, \"A\" * 32764, \"A\" * 32765, \"A\" * 32766, \"A\" * 32767, \"A\" * 32768, \"A\" * 65534, \"A\" * 65535, \"A\" * 65536, \"%x\" * 1024, \"%n\" * 1025 , \"%s\" * 2048, \"%s%n%x%d\" * 5000, \"%s\" * 30000, \"%s\" * 40000, \"%.1024d\", \"%.2048d\", \"%.4096d\", \"%.8200d\", \"%99999999999s\", \"%99999999999d\", \"%99999999999x\", \"%99999999999n\", \"%99999999999s\" * 1000, \"%99999999999d\" * 1000, \"%99999999999x\" * 1000, \"%99999999999n\" * 1000, \"%08x\" * 100, \"%%20s\" * 1000,\"%%20x\" * 1000,\"%%20n\" * 1000,\"%%20d\" * 1000, \"%#0123456x%08x%x%s%p%n%d%o%u%c%h%l%q%j%z%Z%t%i%e%g%f%a%C%S%08x%%#"
