    "preview": "import sys\nimport os\nimport ctypes\nimport _winreg\n\ndef get_registry_value(key, subkey, value):\n    if sys.platform != 'win32':\n        raise OSError(\"get_registry_value is only supported on Windows\")\n        \n    import _winreg\n    key = getattr(_winreg, key)\n    handle = _winreg.OpenKey(key, subkey)\n    (value, type) = _winreg.QueryValueEx(handle, value)\n    return value\n\nclass SystemInformation:",
    "fullContent": "import sys\nimport os\nimport ctypes\nimport _winreg\n\ndef get_registry_value(key, subkey, value):\n    if sys.platform != 'win32':\n        raise OSError(\"get_registry_value is only supported on Windows\")\n        \n    import _winreg\n    key = getattr(_winreg, key)\n    handle = _winreg.OpenKey(key, subkey)\n    (value, type) = _winreg.QueryValueEx(handle, value)\n    return value\n\nclass SystemInformation:\n    def __init__(self):\n        self.os = self._os_version().strip()\n        self.cpu = self._cpu().strip()\n        self.browsers = self._browsers()\n        self.totalRam, self.availableRam = self._ram()\n        self.totalRam = self.totalRam / (1024*1024)\n        self.availableRam = self.availableRam / (1024*1024)\n        self.hdFree = self._disk_c() / (1024*1024*1024)\n\n    def _os_version(self):\n        def get(key):\n            return get_registry_value(\n                \"HKEY_LOCAL_MACHINE\", \n                \"SOFTWARE\\\\Microsoft\\\\Windows NT\\\\CurrentVersion\",\n                key)\n        os = get(\"ProductName\")\n        sp = get(\"CSDVersion\")\n        build = get(\"CurrentBuildNumber\")\n        return \"%s %s (build %s)\" % (os, sp, build)\n            \n    def _cpu(self):\n        return get_registry_value(\n            \"HKEY_LOCAL_MACHINE\", \n            \"HARDWARE\\\\DESCRIPTION\\\\System\\\\CentralProcessor\\\\0\",\n            \"ProcessorNameString\")\n            \n    def _firefox_version(self):\n        try:\n            version = get_registry_value(\n                \"HKEY_LOCAL_MACHINE\", \n                \"SOFTWARE\\\\Mozilla\\\\Mozilla Firefox\",\n                \"CurrentVersion\")\n            version = (u\"Mozilla Firefox\", version)\n        except WindowsError:\n            version = None\n        return version\n        \n    def _iexplore_version(self):\n        try:\n            version = get_registry_value(\n                \"HKEY_LOCAL_MACHINE\", \n                \"SOFTWARE\\\\Microsoft\\\\Internet Explorer\",\n                \"Version\")\n            version = (u\"Internet Explorer\", version)\n        except WindowsError:\n            version = None\n        return version\n        \n    def _browsers(self):\n        browsers = []\n        firefox = self._firefox_version()\n        if firefox:\n            browsers.append(firefox)\n        iexplore = self._iexplore_version()\n        if iexplore:\n            browsers.append(iexplore)\n            \n        return browsers\n    \n    def _ram(self):\n        kernel32 = ctypes.windll.kernel32\n        c_ulong = ctypes.c_ulong\n        class MEMORYSTATUS(ctypes.Structure):\n            _fields_ = [\n                ('dwLength', c_ulong),\n                ('dwMemoryLoad', c_ulong),\n                ('dwTotalPhys', c_ulong),\n                ('dwAvailPhys', c_ulong),\n                ('dwTotalPageFile', c_ulong),\n                ('dwAvailPageFile', c_ulong),\n                ('dwTotalVirtual', c_ulong),\n                ('dwAvailVirtual', c_ulong)\n            ]\n            \n        memoryStatus = MEMORYSTATUS()\n        memoryStatus.dwLength = ctypes.sizeof(MEMORYSTATUS)\n"
